def rank_families(families: list[dict[str, Any]]) -> dict[str, list[str]]:
    rankings: dict[str, list[str]] = {}
    persistence = sorted(families, key=lambda x: (-x['year_count'], -x['event_count'], -x['quartet_count'], -x['anchor_count'], -x['best_score'], x['family_id']))
    rankings['persistence'] = [f['family_id'] for f in persistence]
    for variant in RANKING_VARIANTS[1:]:
        ordered = sorted(families, key=lambda x: (-float(x['ranking_scores'][variant]), -x['year_count'], -x['anchor_count'], x['event_count'], x['family_id']))
        rankings[variant] = [f['family_id'] for f in ordered]
    for variant, ordered in rankings.items():
        for rank, family_id in enumerate(ordered, 1):
            next((f for f in families if f['family_id'] == family_id))['ranks'][variant] = rank
    return rankings
